namespace g2m {
namespace {
using json = nlohmann::json;
using strict::Reader;
// const unsigned char kCarveDefault[]: the bytes of data/carve/carve_default.json, generated by CMake.
#include "carve_default.inc"

bool read_smoothing(Reader& rd, const json& root, CarveSmoothing& out) {
    const auto* s = rd.field(root, "root", "smoothing");
    if (!s || !rd.keys(*s, "smoothing", {"enabled", "radius_m", "kernel", "strength_percent"}) ||
        !rd.boolean(*s, "smoothing", "enabled", out.enabled) ||
        !rd.integer(*s, "smoothing", "radius_m", 0, 16, out.radius_m) ||
        !rd.integer(*s, "smoothing", "strength_percent", 0, 100, out.strength_percent)) return false;
    const auto* kernel = rd.field(*s, "smoothing", "kernel");
    if (!kernel) return false;
    if (!kernel->is_array()) return rd.fail("smoothing.kernel must be an array");
    if (kernel->size() != static_cast<std::size_t>(2 * out.radius_m + 1))
        return rd.fail("smoothing.kernel must have 2 * radius_m + 1 entries");
    for (const auto& w : *kernel) {
        if (!w.is_number_integer() || w.get<std::int64_t>() < 1 || w.get<std::int64_t>() > 65535)
            return rd.fail("smoothing.kernel entries must be integers in [1, 65535]");
        out.kernel.push_back(static_cast<std::int32_t>(w.get<std::int64_t>()));
    }
    for (std::size_t i = 0; i < out.kernel.size() / 2; ++i)
        if (out.kernel[i] != out.kernel[out.kernel.size() - 1 - i]) return rd.fail("smoothing.kernel must be symmetric");
    return true;
}
} // namespace

std::int32_t CarveParams::blend_for_class_mm(std::string_view highway) const {
    const auto it = std::lower_bound(blend.begin(), blend.end(), highway,
        [](const CarveBlendEntry& e, std::string_view h) { return e.highway < h; });
    return it != blend.end() && it->highway == highway ? it->blend_mm : blend_default_mm;
}

RoadSurfaceParams CarveParams::surface_params() const {
    RoadSurfaceParams p;
    p.crown_round_m = static_cast<double>(crown_round_mm) / 1000.0;
    p.verge_drop_m = static_cast<double>(verge_drop_mm) / 1000.0;
    return p;
}

JunctionFadeParams CarveParams::junction_fade_params() const {
    JunctionFadeParams p;
    p.slope = static_cast<double>(junction_fade_slope_per_mille) / 1000.0;
    p.min_m = static_cast<double>(junction_fade_min_mm) / 1000.0;
    p.max_m = static_cast<double>(junction_fade_max_mm) / 1000.0;
    p.verge_m = static_cast<double>(junction_fade_verge_mm) / 1000.0;
    return p;
}

Result<CarveParams> load_carve_params(std::span<const std::byte> bytes) {
    const char* begin = reinterpret_cast<const char*>(bytes.data());
    const json j = json::parse(begin, begin + bytes.size(), nullptr, /*allow_exceptions=*/false);
    if (j.is_discarded()) return make_error(ErrorCode::Malformed, "carve params: not valid JSON");
    Reader rd;
    const auto fail = [&]() { return make_error(ErrorCode::InvalidArgument, "carve params: " + rd.err); };
    if (!rd.keys(j, "root", {"format", "smoothing", "crown_round_mm", "verge_drop_mm", "blend_mm", "blend_slope_factor", "blend_min_mm",
            "blend_max_mm", "deck", "junction_fade", "sources"})) return fail();
    std::string format;
    if (!rd.text(j, "root", "format", format)) return fail();
    if (format != "g2m.carve/1") return make_error(ErrorCode::Unsupported, "carve params: format '" + format + "'");
    CarveParams out;
    if (!read_smoothing(rd, j, out.smoothing) ||
        !rd.integer(j, "root", "crown_round_mm", 1, 2000, out.crown_round_mm) ||
        !rd.integer(j, "root", "verge_drop_mm", 0, 300, out.verge_drop_mm) ||
        !rd.integer(j, "root", "blend_slope_factor", 1, 10, out.blend_slope_factor) ||
        !rd.integer(j, "root", "blend_min_mm", 1, 200000, out.blend_min_mm) ||
        !rd.integer(j, "root", "blend_max_mm", 1, 200000, out.blend_max_mm)) return fail();
    if (out.blend_min_mm > out.blend_max_mm) { rd.fail("blend_min_mm exceeds blend_max_mm"); return fail(); }
    // The junction rules' tile-invariance proof (road_rules.h kCarveBlendMaxM) assumes blends of at most 15 m.
    if (out.blend_max_mm > kCarveBlendMaxM * 1000) { rd.fail("blend_max_mm exceeds the 15 m the junction rules assume"); return fail(); }
    const auto* deck = rd.field(j, "root", "deck");
    if (!deck || !rd.keys(*deck, "deck", {"clearance_mm", "ramp_mm", "margin_mm"}) ||
        !rd.integer(*deck, "deck", "clearance_mm", 1, 5000, out.deck.clearance_mm) ||
        !rd.integer(*deck, "deck", "ramp_mm", 1, 50000, out.deck.ramp_mm) ||
        !rd.integer(*deck, "deck", "margin_mm", 0, 10000, out.deck.margin_mm)) return fail();
    const auto* fade = rd.field(j, "root", "junction_fade");
    if (!fade || !rd.keys(*fade, "junction_fade", {"slope_per_mille", "min_mm", "max_mm", "verge_mm"}) ||
        !rd.integer(*fade, "junction_fade", "slope_per_mille", 1, 1000, out.junction_fade_slope_per_mille) ||
        !rd.integer(*fade, "junction_fade", "min_mm", 1, 100000, out.junction_fade_min_mm) ||
        !rd.integer(*fade, "junction_fade", "max_mm", 1, 100000, out.junction_fade_max_mm) ||
        !rd.integer(*fade, "junction_fade", "verge_mm", 1, 100000, out.junction_fade_verge_mm)) return fail();
    if (out.junction_fade_min_mm > out.junction_fade_max_mm) { rd.fail("junction_fade.min_mm exceeds max_mm"); return fail(); }
    // psi <= phi (D42): the verge term never outlasts the crown term, so z_J stays a convex combination of approach heights.
    if (out.junction_fade_verge_mm > out.junction_fade_min_mm) { rd.fail("junction_fade.verge_mm exceeds min_mm"); return fail(); }
    const auto* sources = rd.field(j, "root", "sources");
    if (!sources || !rd.object(*sources, "sources")) return fail();
    for (auto it = sources->begin(); it != sources->end(); ++it)
        if (!it.value().is_string()) { rd.fail("sources." + it.key() + " must be a string"); return fail(); }

    std::set<std::string> classes;
    for (const auto& entry : RoadStyle::default_style().highways) classes.emplace(std::string(entry.highway));
    const auto* blend = rd.field(j, "root", "blend_mm");
    if (!blend || !rd.object(*blend, "blend_mm")) return fail();
    for (auto it = blend->begin(); it != blend->end(); ++it)
        if (it.key() != "default" && !classes.contains(it.key())) { rd.fail("blend_mm: unknown class '" + it.key() + "'"); return fail(); }
    if (!rd.integer(*blend, "blend_mm", "default", out.blend_min_mm, out.blend_max_mm, out.blend_default_mm)) return fail();
    for (const auto& name : classes) { // ascending highway value
        CarveBlendEntry entry; entry.highway = name;
        if (!blend->contains(name)) { rd.fail("blend_mm: missing class '" + name + "'"); return fail(); }
        if (!rd.integer(*blend, "blend_mm", name.c_str(), out.blend_min_mm, out.blend_max_mm, entry.blend_mm)) return fail();
        out.blend.push_back(std::move(entry));
    }
    out.content_sha256 = Sha256::of(bytes);
    return out;
}

std::span<const std::byte> builtin_carve_default_bytes() {
    return {reinterpret_cast<const std::byte*>(kCarveDefault), sizeof(kCarveDefault)};
}
const CarveParams& builtin_carve_default() {
    static const CarveParams params = [] {
        auto loaded = load_carve_params(builtin_carve_default_bytes());
        if (!loaded) {
            std::fprintf(stderr, "g2m: embedded data/carve/carve_default.json is invalid: %s\n", loaded.error().message.c_str());
            std::abort();
        }
        return std::move(*loaded);
    }();
    return params;
}
} // namespace g2m
